package net.officefloor.hq.app.watch;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The ids of the people on the sheet the user watches (none for no user). */
public class RespondWithWatched {
    public void respond(@PathVariable("sheetId") String sheetId, @RequestParam(name = "user", required = false) String user,
            WatchRepository watches, ObjectResponse<List<Long>> response) {
        response.send(user == null || user.isBlank() ? List.of() : watches.watchedBy(sheetId.trim(), user.trim()));
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the sheet id has never been loaded. */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository)
            throws SheetNotFoundException {
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.exists(id)) {
            throw new SheetNotFoundException(id);
        }
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export const watchesKey = (sheetId: string, user: string) => ['sheet', sheetId, 'watches', user] as const;

/** The ids of the people on the sheet the user watches. */
export function useWatches(sheetId: string, user: string) {
  return useQuery({
    queryKey: watchesKey(sheetId, user),
    queryFn: () =>
      getJson<number[]>(`/api/sheets/${encodeURIComponent(sheetId)}/watches?user=${encodeURIComponent(user)}`),
  });
}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { usePersonError } from '../people/rowError';
import type { Person } from '../people/people';
import { useWatches, watchesKey } from './watch';

/** Whether the signed-in user watches the person, and the toggle that starts or stops it. A watched person's claim
 *  settled, approved or re-settled notifies each watcher (in the audit file). */
function PersonWatch({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const watched = (useWatches(sheetId, user).data ?? []).includes(person.id);
  const { error, setError, begin } = usePersonError(sheetId, person.id);
  const once = useSubmitOnce();

  const toggle = useMutation({
    mutationFn: (on: boolean) =>
      putJson(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/watch`, { user, watched: on }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: watchesKey(sheetId, user) });
    },
    onError: (e) => setError(e instanceof HttpError && e.body ? e.body : `Could not change watching ${person.name}.`),
    onSettled: once.done,
  });

  return (
    <td>
      Watched <span data-testid="person-watched">{watched ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="person-watch"
        disabled={toggle.isPending}
        onClick={() => {
          begin();
          if (!once.start()) return;
          toggle.mutate(!watched);
        }}
      >
        {watched ? 'Unwatch' : 'Watch'}
      </button>
      {error && (
        <p data-testid="person-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 47, Component: PersonWatch });
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's body. Every feature kept per sheet contributes here; the home page renders it
 * only once someone is signed in and a sheet is loaded. Server data under a sheet is keyed
 * ['sheet', sheetId, ...] so a sheet load re-reads all of it.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

