package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.claim.DueBy;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuse the quick-add when the claim's due-by (the terms-th business day after its date — the sheet's entry date, else its today — with the terms it would
 *  get: the named person's, or a new grade A person's) is inside a closed period — before any
 *  person is added, so a refused quick-add leaves nothing behind. */
public class RefuseClosedQuickAdd {
    public void refuse(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, PersonRepository people,
            SheetRepository sheets, SettingRepository settings, HolidayRepository holidays, PeriodRepository periods) throws ClosedPeriodException {
        String id = sheetId.trim();
        periods.lockSheet(id);
        var date = sheets.newClaimDate(id);
        Person found = people.findByName(id, request.name());
        var dueBy = found != null ? DueBy.of(found, date, settings, holidays)
                : holidays.dueBy(id, date, settings.termsFor(id, request.grade(), date));
        Period closed = periods.closedOn(id, dueBy);
        if (closed != null) {
            throw new ClosedPeriodException(closed);
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.DueBy;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Refuse a new claim dated inside a closed period, or whose due-by (its date — a blank date being the sheet's entry date,
 *  else its today — plus the terms it would get) falls inside one. */
public class RefuseClosedNewClaim {
    public void refuse(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            HolidayRepository holidays, PeriodRepository periods)
            throws ClosedPeriodException {
        periods.lockSheet(person.sheetId());
        var date = input.date() != null ? input.date() : sheets.newClaimDate(person.sheetId());
        Period closed = periods.closedOn(person.sheetId(), date);
        if (closed == null) {
            closed = periods.closedOn(person.sheetId(), DueBy.of(person, date, settings, holidays));
        }
        if (closed != null) {
            throw new ClosedPeriodException(closed);
        }
    }
}
